	set elObj = ##class(IHC.ITF.ITFCOMMON.X12.EligibilityRequest).%New()
	Do ..InitFirstObject(elObj, x12Doc, fileName, stat, receiptDtTm ) 

	set parentId = "", objCnt =0
	set GSCounter = x12Doc.ChildCount
	for gsInt=1:1:GSCounter
    { 
        #dim individualGroup As EnsLib.EDI.X12.Document
        set individualGroup = x12Doc.getNthChild(gsInt,2)


		  WRITE !, "# of STs: " _ individualGroup.ChildCount
		  set parentId = "", objCnt =0, elClmObj = $$$NULLOREF // 2100
		  FOR stInd=1:1:individualGroup.ChildCount
		  {

			  #dim STRecord As EnsLib.EDI.X12.Document 

			  set STRecord=individualGroup.getNthChild(stInd,2)

			  set STRecord.DocType = "HIPAA_5010:" _ transType
			  set elObj.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)

			  WRITE !, "ST: " _  transType_ ", Seg Count: " _ STRecord.SegCountGet() 
			  set segX12Data = "", subCnt = 0

	  		  set elObjSub = $$$NULLOREF, hlVal = ""
			  FOR ind=1:1:STRecord.SegCountGet()
			  {

				set segPath = STRecord.GetSegmentPath(ind, .stat)	  	
			  	set segVal = STRecord.GetValueAt(segPath,, .stat)


			  	if ($FIND(segVal,"TRN") = 4)
			  	{

				  	set elObjSub.TrnRefId = $PIECE(segVal, x12Doc.ElementSeparator , 3)
			  	}
			  	elseif ($FIND(segVal,"BHT") = 4)
			  	{
				  	set elObj.BhtId = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	set seg1Val = $PIECE(segVal, x12Doc.ElementSeparator , 7)
				  	if (seg1Val '= "")
				  	{
				  		Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.Bht6Lookup", seg1Val, .retVal)

				  		set elObj.BhtPurpose = retVal 

				  		WRITE !, segVal _" - " _ retVal
				  	}
			  	}
			  	elseif ($FIND(segVal,"DTP") = 4)
			  	{
				  	set seg1Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
				  	Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.DTPLookup", seg1Val, .retVal)

				  	if (seg1Val = "291") // 291: (Plan,Range of dates for which the plan is in effect)
				  	{
				  		set elObjSub.PlanDate = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
			  	}

			  	elseif ($FIND(segVal,"DMG") = 4)
			  	{
				  	if (hlVal = "Subscriber")
				  	{
				  	set elObjSub.SubscriberDOB = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  	set elObjSub.SubscriberGender = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	elseif (hlVal = "Dependent")
				  	{
				  	set elObjSub.DependentDOB = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  	set elObjSub.DependentGender = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
			  	}
			  	elseif ($FIND(segVal,"NM1") = 4)
			  	{

				  	set seg1Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
				  	Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.NM1lookup", seg1Val, .retVal)


				  	if (seg1Val = "PR")
				  	{
					  	set elObj.Provider = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	if (seg1Val = "1P")
				  	{
					  	set elObj.Payer = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	if (seg1Val = "IL")
				  	{
					  	set elObjSub.Subscriber = $PIECE(segVal, x12Doc.ElementSeparator , 4) _ ", " _ $PIECE(segVal, x12Doc.ElementSeparator , 5)
					  	set elObjSub.SubscriberId = $PIECE(segVal, x12Doc.ElementSeparator , 10)
				  	}
				  	if (seg1Val = "03")
				  	{
					  	set elObjSub.Dependent = $PIECE(segVal, x12Doc.ElementSeparator , 4) _ ", " _ $PIECE(segVal, x12Doc.ElementSeparator , 5)
					  	set elObjSub.DependentId = $PIECE(segVal, x12Doc.ElementSeparator , 10)
				  	}
			  	}
			  	elseif ($FIND(segVal,"HL") = 3)
			  	{
	  			  	set seg3Val = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	Do ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.HlCodeLookup", seg3Val, .retVal)
				  	if ($IsObject(elObjSub))
				  	{
					  	Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
					  	set elObjSub.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
					  	set elObjSub.X12DataParentId = parentId
					  	set elObjSub.x12Data = segX12Data
					  	set elObjSub.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)
				  		Do elObjSub.%Save()
				  		Do $INCREMENT(objCnt)
				  		WRITE !, "IHC.ITF.ITFCOMMON.X12.EligibilityRequest ID: " _ elObjSub.%Id()

				  	}
				  	elseif( (elObj.Payer '= "") && (elObj.Provider '= ""))
				  	{
				  		  Do elObj.%Save()
				  		  Do $INCREMENT(objCnt)
						  set parentId = elObj.%Id()					   				  
						  set elObjSub = elObj.%ConstructClone()
						  set elObjSub.x12Data = ""
						  Do elObjSub.x12DataStream.Clear()
						  set elObjSub.SeqNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)
			  		}



				  	set hlVal = retVal // HL level code

				  	if (hlVal = "Subscriber")
				  	{
					  	set elObjSub = elObj.%ConstructClone()
					  	Do elObjSub.x12DataStream.Clear()
					  	set segX12Data = segVal _ STRecord.SegmentTerminator // Start new X12 segment
					  	set elObjSub.SeqNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)
					  	Do $INCREMENT(subCnt)
				  	}
				  	else
				  	{
					  	set segX12Data = segX12Data _ segVal _ STRecord.SegmentTerminator // Append Dependent HL data
				  	}
			  	} //HL

			  	elseif ($FIND(segVal,"ST") = 3)
			  	{
				  	set elObj.TransactionSetControlNumber = $PIECE(segVal, x12Doc.ElementSeparator , 3)
			  	}
			  	elseif ($FIND(segVal,"SE") = 3) 
			  	{

					Do $INCREMENT(^ItfGlobalX12IdKey("X12Data" _ transType))
					set elObjSub.UniqId = ^ItfGlobalX12IdKey("X12Data" _ transType)
					set elObjSub.X12DataParentId = parentId
					set elObjSub.x12Data = segX12Data
					set elObjSub.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)  	
				  	Do elObjSub.%Save()
				  	Do $INCREMENT(objCnt)
			  	}

			  	else
			  	{
				  	// WRITE !, "      ***** Not stored: " _ segVal
			  	}
			  	if ($FIND(segVal,"HL") '= 3)
			  	{
			  		set segX12Data = segX12Data _ segVal _ STRecord.SegmentTerminator // Append data
			  	}
			  }
		  }
		  set elObj.SeqNum = subCnt
		  Do elObj.%Save()
    }
	WRITE !, " --- Processing complete: IHC.ITF.ITFCOMMON.X12.EligibilityRequest, # rows:" _ objCnt

