			   {
			   	  // WRITE !, "SenderID: " _ interchangeReceiverID _ ", GroupControlNumber: " _ GroupControlNumber // _ ", " _ individualST.OutputToString()
			   	  set cur2000pathIK="loop2000("_loopNum_").IK5"
			      set cur2000ind=individualST.GetSegmentIndex(cur2000pathIK,.cur2000status)

				  set ackObj = ##class(IHC.ITF.ITFCOMMON.X12.ImplementationAcknowledgment).%New()
				  set ackObj.InterchangeReceiverID = interchangeReceiverID
				  set ackObj.InterchangeSenderID = interchangeSenderID
				  set ackObj.ApplicationReceiversCode = GS03
				  set ackObj.ApplicationSendersCode = GS02
				  set ackObj.GroupControlNumber = GroupControlNumber
				  set ackObj.GroupIdentifierCode = individualST.GetValueAt("AK1:1")
				  set ackObj.GroupVersion = individualST.GetValueAt("AK1:3")
				  set ackObj.GroupRespFunctionalGroupAcknowledge = GroupAckCode
				  set ackObj.GroupRespNumberofTransactionSets = individualST.GetValueAt("AK9:2")
				  set ackObj.GroupRespAcceptedTransactions = individualST.GetValueAt("AK9:4")
				  set ackObj.TransIdentifierCode = individualST.GetValueAt(cur2000path_":1")
				  set ackObj.TransControlNumber = individualST.GetValueAt(cur2000path_":2")
				  set ackObj.TransVersion = individualST.GetValueAt(cur2000path_":3") 
				  set ackObj.UniqId = ^ItfGlobalX12IdKey("X12Data999")

				  set ackObj.InterchangeControlNumber = x12Doc.GetValueAt("ISA:InterchangeControlNumber")
				  set ackObj.InterchangeDateTime= $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeDate"), "<>W") _ $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeTime"), "<>W")
				  set ackObj.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)
				  set ackObj.ReceiptDtTm = receiptDtTm
				  set ackObj.Status = "Processed"

				  set ackObj.FileName = ##class(%File).GetFilename(flNm)
		  			set ackObj.MonthPartition = mmId



				  if ( (GSnum = 1) && (STnum = 1) && (loopNum = 1))
				  {
					  set fileSz = ##class(%File).GetFileSize(flNm)
					  if (fileSz  > 3641143) // Property x12Data As %String(MAXLEN = 3641144);
					  {

						  Set stream=##class(%FileCharacterStream).%New()
			    		  Set stream.Filename=flNm
			    		  set ackObj.x12DataStream = stream

					  }
					  else
					  {
					      set ackObj.x12Data = x12Doc.OutputToString(,.stat,)
					      if (stat '= 1)
					      {
						      WRITE !, " --- The length of the document is greater than the maximum string length ---"
					      }
					  }  
					  set stat = ackObj.%Save()
					  Do $INCREMENT(objCnt)
					  set parentId = ackObj.%Id()
					  set ak2Obj = ackObj.%ConstructClone()
					  set ak2Obj.x12Data = individualST.OutputToString()
				   	  set ak2Obj.X12DataParentId = parentId
				   	  set stat = ak2Obj.%Save()
				   	  Do $INCREMENT(objCnt)
			   	  }
			   	  else
			   	  {
				   	  set ackObj.x12Data = individualST.OutputToString()
				   	  set ackObj.X12DataParentId = parentId
				   	  set stat = ackObj.%Save()
				   	  Do $INCREMENT(objCnt)
			   	  }

				  Do $INCREMENT(^ItfGlobalX12IdKey("X12Data999"))
				  WRITE !, "GS-" _ GSnum _", ST: " _ STnum _ ", Ak2: " _ loopNum _  ", TransSetAckCode= " _ individualST.GetValueAt(cur2000pathIK_":1") _", GroupAckCode: " _ GroupAckCode _  ", Id: " _ ackObj.%Id() _", stat: " _ stat


			   }
			   Do $INCREMENT(loopNum)
	          }

             Do $INCREMENT(STnum)
          } 
          Do $INCREMENT(GSnum) 

     }
  }
  WRITE !, " --- Processing complete: IHC.ITF.ITFCOMMON.X12.ImplementationAcknowledgment, # rows:" _ objCnt

set transType = STRecord.GetValueAt("1:1",, .stat)


  if (STRecord.GetValueAt("1",, .stat) [ "005010X222A1")
	{
		set transType = transType _"P"
	}
	elseif (STRecord.GetValueAt("1",, .stat) [ "005010X223A2")
	{
		set transType = transType _"I"
	}
	elseif (STRecord.GetValueAt("1",, .stat) [ "005010X224A2")
	{
		set transType = transType _"D"
	}
	elseif (STRecord.GetValueAt("1",, .stat) [ "005010X214")
	{
		set transType = transType _"CA"
	}
return transType

		   set InterchangeCtrlNum = x12Doc.GetValueAt("ISA:InterchangeControlNumber")
		   set InterchangeSenderID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeSenderID"), "<>W")
		   set InterchangeReceiverID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeReceiverID"), "<>W")

		  set mmId = $EXTRACT($ZDATE($HOROLOG, 8), 1, 6)

		   set elObj.FileName = ##class(%File).GetFilename(fileName)
		  set elObj.MonthPartition = mmId

		  set elObj.InterchangeControlNumber = x12Doc.GetValueAt("ISA:InterchangeControlNumber")
		  set elObj.InterchangeDateTime = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeDate"), "<>W") _ $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeTime"), "<>W")
		  set elObj.InterchangeReceiverID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeReceiverID"), "<>W")
		  set elObj.InterchangeSenderID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeSenderID"), "<>W")
		  if (x12Doc.ChildCount > 0)
		  {

			  #dim individualGroup As EnsLib.EDI.X12.Document 
			  set individualGroup = x12Doc.getNthChild(1,2)

			  set isaGsInfo =  InterchangeSenderID _" -> " _ InterchangeReceiverID _ ", ControlNumbers: " _ InterchangeCtrlNum _", " _ individualGroup.GetValueAt("GS:GroupControlNumber")
		      WRITE !, "# of STs: " _ individualGroup.ChildCount 

			  set elObj.GroupControlNumber = individualGroup.GetValueAt("GS:GroupControlNumber")
			  set elObj.ApplicationReceiversCode = individualGroup.GetValueAt("GS:ApplicationReceiversCode")
			  set elObj.ApplicationSendersCode = individualGroup.GetValueAt("GS:ApplicationSendersCode")
			  set elObj.VersionReleaseIndustryIdenti =  individualGroup.GetValueAt("GS:VersionReleaseIndustryIdenti")
		  }
		  set elObj.ProcessDtTm = $ZDATETIME($HOROLOG,3, 1)
		  set elObj.ReceiptDtTm = receiptDtTm
		  set elObj.Status = stat


		  if (##class(%File).GetFileSize(fileName)  > 3641143) // Property x12Data As %String(MAXLEN = 3641144);
		  {

			  Set stream=##class(%FileCharacterStream).%New()
    		  // Set stream.Filename=flNm
    		  set elObj.x12DataStream = stream

		  }
		  else
		  {
		      set elObj.x12Data = x12Doc.OutputToString(,.stat,)
		      if (stat '= 1)
		      {
			      WRITE !, " --- The length of the document is greater than the maximum string length ---"
		      }
	}
